-- =============================================
-- Lotes al Mando - Roles, permisos y asignaciones
-- Ejecutar despues de 001_initial_schema.sql y 002_seed_data.sql
-- =============================================

-- Tablas de seguridad de aplicacion.
-- NOTA (actualizada tras confirmar el schema real via dump del usuario):
-- estas tablas SI estan definidas en 001_initial_schema.sql, que corre
-- primero, con columnas ligeramente distintas a las de aqui debajo
-- (INTEGER GENERATED BY DEFAULT AS IDENTITY en vez de BIGSERIAL,
-- UNIQUE(nombre_permiso, modulo) en vez de UNIQUE(nombre_permiso) solo,
-- y usuario_rol con PK compuesta (id_usuario, id_rol) sin columna
-- surrogate id_usuario_rol). Los CREATE TABLE de aqui abajo quedan como
-- no-ops de compatibilidad (por el IF NOT EXISTS) - la definicion real
-- vigente es la de 001. No se borran para no romper si alguien corre
-- este archivo suelto contra un proyecto que no tiene 001 aplicado.
CREATE TABLE IF NOT EXISTS roles (
  id_rol BIGSERIAL PRIMARY KEY,
  nombre_rol TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS permiso (
  id_permiso BIGSERIAL PRIMARY KEY,
  nombre_permiso TEXT NOT NULL UNIQUE,
  modulo TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS rol_permiso (
  id_rol_permiso BIGSERIAL PRIMARY KEY,
  id_rol BIGINT NOT NULL REFERENCES roles(id_rol) ON DELETE CASCADE,
  id_permiso BIGINT NOT NULL REFERENCES permiso(id_permiso) ON DELETE CASCADE,
  UNIQUE (id_rol, id_permiso)
);

CREATE TABLE IF NOT EXISTS usuario_rol (
  id_usuario_rol BIGSERIAL PRIMARY KEY,
  id_usuario BIGINT NOT NULL REFERENCES usuario(id_usuario) ON DELETE CASCADE,
  id_rol BIGINT NOT NULL REFERENCES roles(id_rol) ON DELETE CASCADE,
  fecha_asignacion DATE NOT NULL DEFAULT CURRENT_DATE,
  UNIQUE (id_usuario, id_rol)
);

-- Catalogo base de roles.
INSERT INTO roles (id_rol, nombre_rol)
VALUES
  (1, 'Administrador'),
  (2, 'Vendedor'),
  (3, 'Gerente')
ON CONFLICT (id_rol) DO UPDATE
SET nombre_rol = EXCLUDED.nombre_rol;

-- Catalogo base de permisos.
INSERT INTO permiso (id_permiso, nombre_permiso, modulo)
VALUES
  (1, 'crear_proyectos', 'proyectos'),
  (2, 'editar_proyectos', 'proyectos'),
  (3, 'eliminar_proyectos', 'proyectos'),
  (4, 'ver_proyectos', 'proyectos'),
  (5, 'crear_lotes', 'lotes'),
  (6, 'editar_lotes', 'lotes'),
  (7, 'cambiar_estado_lotes', 'lotes'),
  (8, 'crear_ventas', 'ventas'),
  (9, 'aprobar_ventas', 'ventas'),
  (10, 'anular_ventas', 'ventas'),
  (11, 'crear_clientes', 'clientes'),
  (12, 'editar_clientes', 'clientes'),
  (13, 'ver_clientes', 'clientes'),
  (14, 'ver_cobranzas', 'cobranzas'),
  (15, 'registrar_pago', 'cobranzas'),
  (16, 'ver_pagos', 'pagos'),
  (17, 'confirmar_pagos', 'pagos'),
  (18, 'ver_reportes', 'reportes'),
  (19, 'exportar_reportes', 'reportes'),
