ON CONFLICT (id_permiso) DO UPDATE
SET nombre_permiso = EXCLUDED.nombre_permiso,
    modulo = EXCLUDED.modulo;

-- Administrador recibe todos los permisos.
INSERT INTO rol_permiso (id_rol, id_permiso)
SELECT 1, permiso.id_permiso
FROM permiso
ON CONFLICT (id_rol, id_permiso) DO NOTHING;

-- Vendedor recibe permisos operativos.
INSERT INTO rol_permiso (id_rol, id_permiso)
SELECT 2, permiso.id_permiso
FROM permiso
WHERE permiso.nombre_permiso IN (
  'ver_proyectos',
  'cambiar_estado_lotes',
  'crear_ventas',
  'crear_clientes',
  'editar_clientes',
  'ver_clientes',
  'ver_cobranzas',
  'registrar_pago',
  'ver_pagos',
  'ver_reportes'
)
ON CONFLICT (id_rol, id_permiso) DO NOTHING;

-- Gerente recibe permisos de supervision y operacion.
INSERT INTO rol_permiso (id_rol, id_permiso)
SELECT 3, permiso.id_permiso
FROM permiso
WHERE permiso.nombre_permiso IN (
  'crear_proyectos',
  'editar_proyectos',
  'ver_proyectos',
  'crear_lotes',
  'editar_lotes',
  'cambiar_estado_lotes',
  'crear_ventas',
  'aprobar_ventas',
  'anular_ventas',
  'crear_clientes',
  'editar_clientes',
  'ver_clientes',
  'ver_cobranzas',
  'registrar_pago',
  'ver_pagos',
  'confirmar_pagos',
  'ver_reportes',
  'exportar_reportes'
)
ON CONFLICT (id_rol, id_permiso) DO NOTHING;

-- Asignaciones de ejemplo solo para usuarios existentes.
-- No crea usuarios ficticios ni falla si todavia no se han registrado.
INSERT INTO usuario_rol (id_usuario, id_rol, fecha_asignacion)
SELECT usuario.id_usuario, roles.id_rol, CURRENT_DATE
FROM usuario
CROSS JOIN roles
WHERE usuario.email = 'admin@lotes.com'
  AND roles.nombre_rol = 'Administrador'
ON CONFLICT (id_usuario, id_rol) DO NOTHING;

-- Mantiene las secuencias despues de fijar IDs explicitos en el catalogo.
SELECT setval(
  pg_get_serial_sequence('roles', 'id_rol'),
  COALESCE((SELECT MAX(id_rol) FROM roles), 1),
  true
);

SELECT setval(
  pg_get_serial_sequence('permiso', 'id_permiso'),
  COALESCE((SELECT MAX(id_permiso) FROM permiso), 1),
  true
);
